const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function tradePolicyHTML(D,data,e){
 const states=D.states.filter(s=>s.i&&s.i!==17),sn=id=>states.find(s=>s.i===id)?.name.trim()||'—',opts=()=>states.map(s=>`<option value="${s.i}">${esc(s.name.trim())}</option>`).join(''),reverse=()=>[...states].reverse().map(s=>`<option value="${s.i}">${esc(s.name.trim())}</option>`).join(''),gn=id=>data.goods.find(g=>g.i===id)?.name||id;
 return `<section class="tradePolicies"><h3>Políticas de comércio e navegação</h3><p class="muted">Aliança: −10%; amizade: −5%; desconfiança: +15%; rivalidade: +20%; inimizade: +35%. O desconto respeita o custo dos insumos registrado no estoque e um custo operacional de referência. Guerra bloqueia o comércio. Valores locais de referência não dependem de um comprador específico.</p>
 <details open><summary>Embargos gerais ou por bem</summary><form id="policyEmbargo"><label>Estado que impõe<select id="embargoFrom">${opts()}</select></label><label>Estado atingido<select id="embargoTo">${reverse()}</select></label><label>Bem<select id="embargoGood"><option value="all">Todos os bens</option>${data.goods.map(g=>`<option value="${g.i}">${esc(g.name)}</option>`).join('')}</select></label><button>Aplicar embargo</button></form><p class="muted">Impede compras e vendas dos bens escolhidos entre os dois estados. Não fecha estradas a terceiros.</p>${(e.embargoes||[]).map((r,i)=>`<p>${esc(sn(r.from))} → ${esc(sn(r.to))}: ${r.goods.length?r.goods.map(gn).map(esc).join(', '):'todos os bens'} <button data-remove-embargo="${i}">Retirar embargo</button></p>`).join('')||'<p class="muted">Sem embargo ativo.</p>'}</details>
 <details><summary>Tarifas alfandegárias</summary><form id="policyTariff"><label>Estado importador<select id="tariffState"><option value="all">Padrão para todos os estados</option>${opts()}</select></label><label>Tarifa de importação · %<input id="tariffRate" type="number" min="0" max="100" step="1" value="${e.defaultTariff*100}"></label><button>Salvar tarifa</button></form><p class="muted">Padrão: ${e.defaultTariff*100}%. Cobrança sobre o preço da mercadoria importada, sem frete; o valor entra no caixa aduaneiro do estado. Compras internas não pagam.</p>${Object.entries(e.stateTariffs||{}).map(([id,rate])=>`<p>${esc(sn(+id))}: ${rate*100}% <button data-remove-tariff="${id}">Usar padrão</button></p>`).join('')}</details>
 <details><summary>Bloqueios navais de portos</summary><form id="policyBlockade"><label>Estado bloqueador<select id="blockadeBy">${opts()}</select></label><label>Portos do estado<select id="blockadeState">${reverse()}</select></label><button>Aplicar bloqueio naval</button></form><p class="muted">Fecha os trechos marítimos que entram ou saem dos portos do estado atingido. O comércio tenta caminhos terrestres ou outros fornecedores. Não cria guerra automaticamente.</p>${(e.navalBlockades||[]).map((r,i)=>`<p>${esc(sn(r.by))} bloqueia os portos de ${esc(sn(r.state))} <button data-remove-blockade="${i}">Levantar bloqueio</button></p>`).join('')||'<p class="muted">Sem bloqueio naval ativo.</p>'}</details>
 <details><summary>Pirataria regional</summary><form id="policyPiracy"><label>Águas próximas de<select id="piracyState">${opts()}</select></label><label>Risco máximo por trecho · %<input id="piracyRisk" type="number" min="0" max="50" step="1" value="12"></label><label>Alcance a partir da costa · unidades do mapa<input id="piracyRadius" type="number" min="4" max="300" step="1" value="90"></label><button>Salvar região de pirataria</button></form><p class="muted">A intensidade diminui longe da costa. A simulação aplica uma perda média de carga, sem sorteio; o custo por unidade entregue aumenta. As mercadorias perdidas e os valores pagos aparecem no ciclo.</p>${(e.piracyZones||[]).map((r,i)=>`<p>${esc(sn(r.state))}: até ${Math.round(r.risk*100)}% · ${r.radius} unidades <button data-remove-piracy="${i}">Remover região</button></p>`).join('')||'<p class="muted">Sem risco regional de pirataria.</p>'}</details>
 <details><summary>Comboios de escolta</summary><form id="policyConvoys"><label><input id="convoysEnabled" type="checkbox" ${e.convoys?'checked':''}> Organizar comboios nas rotas marítimas</label><p class="muted">Decisão operacional opcional, sem criar uma aliança. Reduz em 35% o risco médio de cada trecho marítimo e aumenta seu frete em 10% para pagar a escolta.</p><button>Salvar comboios</button></form></details><details><summary>Preços por escassez</summary><form id="policyScarcity"><label>Intensidade do ajuste · %<input id="scarcityStrength" type="number" min="0" max="200" step="5" value="${e.scarcityStrength*100}"></label><button>Salvar escassez</button></form><p class="muted">Demanda superior à produção e ao estoque eleva o preço local. Excedentes reduzem o preço. O ajuste vai de 65% a 250% da referência regional; intensidade zero desativa. São estimativas do cenário, não inflação monetária.</p></details></section>`;
}
export function bindTradePolicies(root,{getEdits,onSave,toast}){
 const $=s=>root.querySelector(s),perform=fn=>{try{onSave(fn(structuredClone(getEdits())));toast('Política salva; economia recalculada.');}catch(e){toast(e.message);}};
 if($('#tariffState'))$('#tariffState').onchange=()=>{const e=getEdits(),id=$('#tariffState').value;$('#tariffRate').value=100*(id==='all'?e.defaultTariff:e.stateTariffs[id]??e.defaultTariff);};
 if($('#piracyState'))$('#piracyState').onchange=()=>{const z=getEdits().piracyZones.find(z=>z.state===+$('#piracyState').value);$('#piracyRisk').value=(z?.risk??.12)*100;$('#piracyRadius').value=z?.radius??90;};
 if($('#policyEmbargo'))$('#policyEmbargo').onsubmit=event=>{event.preventDefault();const from=+$('#embargoFrom').value,to=+$('#embargoTo').value,g=$('#embargoGood').value;perform(e=>{const row=e.embargoes.find(r=>r.from===from&&r.to===to);if(row){if(g==='all')row.goods=[];else if(row.goods.length)row.goods=[...new Set([...row.goods,+g])];}else e.embargoes.push({from,to,goods:g==='all'?[]:[+g]});return e;});};
 if($('#policyTariff'))$('#policyTariff').onsubmit=event=>{event.preventDefault();const id=$('#tariffState').value,rate=Number($('#tariffRate').value)/100;perform(e=>{if(id==='all')e.defaultTariff=rate;else e.stateTariffs[id]=rate;return e;});};
 if($('#policyBlockade'))$('#policyBlockade').onsubmit=event=>{event.preventDefault();const by=+$('#blockadeBy').value,state=+$('#blockadeState').value;perform(e=>{e.navalBlockades.push({by,state});return e;});};
 if($('#policyPiracy'))$('#policyPiracy').onsubmit=event=>{event.preventDefault();const state=+$('#piracyState').value,risk=Number($('#piracyRisk').value)/100,radius=Number($('#piracyRadius').value);perform(e=>{e.piracyZones=e.piracyZones.filter(r=>r.state!==state);e.piracyZones.push({state,risk,radius});return e;});};
 if($('#policyConvoys'))$('#policyConvoys').onsubmit=event=>{event.preventDefault();perform(e=>({...e,convoys:$('#convoysEnabled').checked}));};
 if($('#policyScarcity'))$('#policyScarcity').onsubmit=event=>{event.preventDefault();const intensity=Number($('#scarcityStrength').value)/100;perform(e=>({...e,scarcityStrength:intensity}));};
 for(const [selector,key]of [['embargo','embargoes'],['blockade','navalBlockades'],['piracy','piracyZones']])for(const button of root.querySelectorAll(`[data-remove-${selector}]`))button.onclick=()=>perform(e=>{e[key].splice(+button.getAttribute('data-remove-'+selector),1);return e;});
 for(const button of root.querySelectorAll('[data-remove-tariff]'))button.onclick=()=>perform(e=>{delete e.stateTariffs[button.dataset.removeTariff];return e;});
}
